package com.chiru.engine.docs;

import com.chiru.engine.model.*;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/**
 * Phase 11: the functional documents, for business analysts and subject matter experts. They describe the same analysed facts as
 * documents 01 to 14 in business words: what the application does end to end, what each scenario decides, what every output field
 * means and where it comes from, the terms used, and what still needs a person to confirm.
 *
 * <p>Nothing here is generated by a model or guessed: sentences come from fixed templates over the extracted facts, and the English for
 * conditions and calculations comes from {@link Humanizer}, which only rewrites the code it was given. Where the code does not say what
 * a name means, the document says so and asks (F06) rather than inventing a meaning.
 */
final class FunctionalDocs {

    private FunctionalDocs() {}

    private static final int DIAGRAM_PATH_LIMIT = 16;

    private static String header(String title, String purpose) {
        return Md.h(1, title) + "_" + purpose + "_\n\n"
                + "> Generated from `analysis-model.json` (schema version " + AnalysisModel.SCHEMA_VERSION + "). Written for business analysts and subject matter experts. Every statement is derived from the code by fixed rules "
                + "(no AI, no guessing); the technical evidence behind it is in documents 01 to 14. Names are only **spelled out** from the "
                + "code (`rate_pct` reads \"rate percent\"): where the code does not say what a name means, the question is listed in "
                + "[F06](F06_Questions_For_Business_Experts.md). Business names can be set in `glossary.properties` "
                + "(see [F05](F05_Glossary.md)).\n\n";
    }

    // ================================================================ shared facts

    private record Writer(Entity file, String layoutClassPrefix) {}

    /** What the application reads, writes and updates, taken from the model. */
    private static final class Facts {
        final DocContext c;
        final Humanizer h;
        final List<Entity> scenarios;
        final List<Entity> selects;
        final List<Entity> updates;
        final List<Entity> files;
        final List<Entity> entryPoints;
        final Set<String> formattingPrefixes = new HashSet<>();

        Facts(DocContext c) {
            this.c = c;
            this.h = c.humanizer;
            scenarios = c.of(EntityType.SCENARIO).stream().sorted(Comparator.comparing(e -> label(e))).toList();
            selects = c.of(EntityType.SQL_STATEMENT).stream().filter(s -> "SELECT".equals(c.attr(s, "type"))).toList();
            updates = c.of(EntityType.SQL_STATEMENT).stream().filter(s -> !"SELECT".equals(c.attr(s, "type"))).toList();
            files = c.of(EntityType.OUTPUT_FILE);
            entryPoints = c.of(EntityType.METHOD).stream().filter(m -> c.attr(m, "entryPoint") != null).toList();
            for (Entity f : files) {
                String layout = c.attr(f, "layoutMethod");
                if (layout != null && layout.contains("#")) {
                    formattingPrefixes.add(layout.substring(0, layout.indexOf('#') + 1));       // rules in the writer class lay out text, they are not business rules
                }
            }
        }

        String label(Entity scenario) {
            String l = c.attr(scenario, "label");
            return l == null ? scenario.name() : l;
        }

        boolean isFormatting(String methodId) {
            return methodId != null && formattingPrefixes.stream().anyMatch(methodId::startsWith);
        }

        String entryText() {
            return entryPoints.isEmpty() ? "the application" : entryPoints.stream().map(m -> jobName(c.method(m.id().value()))).distinct().collect(Collectors.joining(", "));
        }

        /** {@code BatchJob.main} as "the batch job". */
        String jobName(String shortName) {
            String type = shortName.contains(".") ? shortName.substring(0, shortName.indexOf('.')) : shortName;
            String words = h.words(type).replaceAll("\s*(job|batch|main|runner|application|app)$", "").trim();
            return "the " + (words.isEmpty() ? "main" : words) + " job";
        }
    }

    // ================================================================ F01 overview

    static String overview(DocContext c) {
        Facts f = new Facts(c);
        StringBuilder sb = new StringBuilder(header("F01 Business overview", "What the application does, in one page."));
        sb.append(Md.h(2, "In short"));
        if (c.answers.containsKey("system.purpose")) {
            sb.append("**Purpose (provided by the business):** ").append(c.answers.get("system.purpose")).append("\n\n");
            if (c.answers.containsKey("system.users")) {
                sb.append("**Who uses the result:** ").append(c.answers.get("system.users")).append("\n\n");
            }
        }
        StringBuilder story = new StringBuilder("The application is started by " + f.entryText() + ". ");
        List<String> tables = readTables(c, f);
        if (!tables.isEmpty()) {
            story.append("It reads ").append(tables.size() == 1 ? "records" : "records").append(" from the ")
                    .append(String.join(" and ", tables)).append(" table").append(tables.size() > 1 ? "s" : "").append(". ");
        }
        if (!f.scenarios.isEmpty()) {
            story.append("For each record it decides which kind of work applies (")
                    .append(f.scenarios.stream().map(s -> "**" + f.label(s) + "**").collect(Collectors.joining(", ")))
                    .append(") and handles it accordingly. ");
        }
        List<Entity> fields = c.fields();
        if (!f.files.isEmpty()) {
            story.append("It then writes ").append(f.files.size() == 1 ? "a file" : f.files.size() + " files").append(" with ")
                    .append(fields.size()).append(" field").append(fields.size() == 1 ? "" : "s").append(" per line (")
                    .append(fields.stream().map(x -> h(f, x.name())).collect(Collectors.joining(", "))).append("). ");
        }
        List<String> updated = f.updates.stream().map(u -> c.name(u.id())).distinct().toList();
        if (!updated.isEmpty()) {
            story.append("Finally it saves the results back to the database (").append(String.join("; ", updated)).append(").");
        }
        sb.append(story.toString().trim()).append("\n\n");
        sb.append("The step-by-step flow with a diagram is in [F02](F02_End_To_End_Business_Flow.md); the rules of each kind of work are in "
                + "[F03](F03_Business_Scenarios_And_Rules.md).\n\n");

        sb.append(Md.h(2, "Kinds of work (scenarios)"));
        List<List<String>> rows = new ArrayList<>();
        for (Entity s : f.scenarios) {
            rows.add(List.of(f.label(s), f.h.words(s.name()),
                    "When " + f.h.condition(c.attr(s, "trigger")),
                    c.attr(s, "outputFields") == null ? Md.NONE : Arrays.stream(c.attr(s, "outputFields").split(", ")).map(x -> h(f, x)).collect(Collectors.joining(", "))));
        }
        sb.append(Md.table(List.of("Kind of work", "Handled by", "Applies when", "Fills these output fields"), rows));

        sb.append(Md.h(2, "What goes in"));
        List<List<String>> in = new ArrayList<>();
        for (Entity s : f.selects) {
            in.add(List.of(sqlTitle(c, s, f), selectedColumns(s, f), filterText(c.attr(s, "predicates"), f.h)));
        }
        sb.append(Md.table(List.of("Data read", "Fields used", "Only records where"), in));

        sb.append(Md.h(2, "What comes out"));
        List<List<String>> out = new ArrayList<>();
        for (Entity file : f.files) {
            out.add(List.of(fileTitle(c, f, file.id().value()), "fixed-width text file, " + c.attr(file, "fieldCount") + " fields per line",
                    fields.stream().filter(x -> file.id().value().equals(c.attr(x, "file"))).map(x -> h(f, x.name())).collect(Collectors.joining(", "))));
        }
        for (Entity u : f.updates) {
            out.add(List.of(sqlTitle(c, u, f), "database update", updateText(u, f)));
        }
        sb.append(Md.table(List.of("Result", "Form", "Content"), out));
        sb.append("_Where this came from: " + c.of(EntityType.CLASS).stream().filter(x -> !"true".equals(c.attr(x, "external"))).count()
                + " classes analysed; technical inventory in [02](02_Functionality_Inventory.md)._\n");
        return sb.toString();
    }

    private static String h(Facts f, String fieldName) {
        return f.h.words(fieldName);
    }

    private static String sqlTitle(DocContext c, Entity s, Facts f) {
        Matcher m = Pattern.compile("(?i)\\b(?:FROM|UPDATE|INTO)\\s+(\\w+)").matcher(c.attr(s, "text") == null ? "" : c.attr(s, "text"));
        String table = m.find() ? f.h.words(m.group(1)) : c.name(s.id());
        return ("SELECT".equals(c.attr(s, "type")) ? "Records read from the " : "Records saved to the ") + table + " table";
    }

    private static List<String> readTables(DocContext c, Facts f) {
        Set<String> tables = new TreeSet<>();
        for (Entity s : f.selects) {
            Matcher m = Pattern.compile("(?i)\\bFROM\\s+(\\w+)").matcher(c.attr(s, "text") == null ? "" : c.attr(s, "text"));
            while (m.find()) {
                tables.add(f.h.words(m.group(1)));
            }
        }
        return new ArrayList<>(tables);
    }

    private static String selectedColumns(Entity s, Facts f) {
        String text = f.c.attr(s, "text");
        Matcher m = Pattern.compile("(?is)^SELECT\\s+(.*?)\\s+FROM\\s+(\\w+)").matcher(text == null ? "" : text);
        if (!m.find()) {
            return Md.NONE;
        }
        String table = m.group(2);
        return Arrays.stream(m.group(1).split(",")).map(String::trim).map(col -> col.replaceAll("^\\w+\\.", ""))
                .map(col -> f.h.column(table, col)).collect(Collectors.joining(", "));
    }

    private static String updateText(Entity u, Facts f) {
        String text = f.c.attr(u, "text");
        Matcher m = Pattern.compile("(?is)^UPDATE\\s+(\\w+)\\s+SET\\s+(.*?)(?:\\s+WHERE\\s+(.*))?$").matcher(text == null ? "" : text);
        if (!m.find()) {
            return text == null ? Md.NONE : Md.code(text);
        }
        String set = Arrays.stream(m.group(2).split(",")).map(x -> x.split("=")[0].trim())
                .map(col -> f.h.column(m.group(1), col)).collect(Collectors.joining(", "));
        return "Updates " + set + (m.group(3) == null ? "" : " for the record whose " + filterText(m.group(3), f.h));
    }

    /** SQL conditions in words: {@code a.due_date <= ?} reads "due date is on or before the run-time value". */
    static String filterText(String predicates, Humanizer h) {
        if (predicates == null || predicates.isBlank()) {
            return "all records";
        }
        String p = predicates.trim().replaceFirst("(?i)^WHERE\\s+", "");
        p = p.replaceAll("\\b[A-Za-z_]\\w*\\.(?=[A-Za-z_])", "");
        Matcher in = Pattern.compile("(?i)(\\w+)\\s+IN\\s*\\(([^)]*)\\)").matcher(p);
        StringBuilder sb = new StringBuilder();
        while (in.find()) {
            in.appendReplacement(sb, Matcher.quoteReplacement(h.words(in.group(1)) + " is one of " + in.group(2).replaceAll("\\s*,\\s*", ", ")));
        }
        in.appendTail(sb);
        p = sb.toString();
        Matcher cmp = Pattern.compile("(\\w+)\\s*(<=|>=|<>|!=|=|<|>)\\s*(\\?|'[^']*'|\\d+(?:\\.\\d+)?)").matcher(p);
        sb = new StringBuilder();
        while (cmp.find()) {
            boolean date = cmp.group(1).toLowerCase(Locale.ROOT).contains("date") || cmp.group(1).toLowerCase(Locale.ROOT).endsWith("dt");
            String op = switch (cmp.group(2)) {
                case "<=" -> date ? "is on or before" : "is at most";
                case ">=" -> date ? "is on or after" : "is at least";
                case "<" -> date ? "is before" : "is less than";
                case ">" -> date ? "is after" : "is greater than";
                case "=" -> "is";
                default -> "is not";
            };
            String value = cmp.group(3).equals("?") ? "the value supplied at run time" : cmp.group(3);
            cmp.appendReplacement(sb, Matcher.quoteReplacement(h.words(cmp.group(1)) + " " + op + " " + value));
        }
        cmp.appendTail(sb);
        return sb.toString().replaceAll("(?i)\\s+AND\\s+", " and ").replaceAll("(?i)\\s+OR\\s+", " or ");
    }

    // ================================================================ F02 end-to-end flow

    static String endToEnd(DocContext c) {
        Facts f = new Facts(c);
        StringBuilder sb = new StringBuilder(header("F02 End-to-end business flow", "From the start of the job to the result, step by step."));
        List<String> steps = new ArrayList<>();
        StringBuilder mm = new StringBuilder("flowchart TD\n");
        String prev = "start";
        mm.append("  start([\"Start: ").append(esc(f.entryPoints.isEmpty() ? "application starts" : f.jobName(c.method(f.entryPoints.get(0).id().value())))).append("\"])\n");
        steps.add("**Start.** " + Character.toUpperCase(f.entryText().charAt(0)) + f.entryText().substring(1) + " begins the run.");
        int n = 0;
        for (Entity s : f.selects) {
            String node = "read" + (++n);
            String text = "Read " + String.join(", ", readTablesOf(c, s, f)) + " records where " + filterText(c.attr(s, "predicates"), f.h);
            mm.append("  ").append(prev).append(" --> ").append(node).append("[\"").append(esc(cut(text, 110))).append("\"]\n");
            steps.add("**Read the data.** " + text + ".");
            prev = node;
        }
        if (!f.scenarios.isEmpty()) {
            mm.append("  ").append(prev).append(" --> route{\"Which kind of work?\"}\n");
            steps.add("**Decide the kind of work.** Each record is routed by its status: "
                    + f.scenarios.stream().map(s -> "**" + f.label(s) + "** when " + f.h.condition(c.attr(s, "trigger"))).collect(Collectors.joining("; ")) + ".");
            int k = 0;
            for (Entity s : f.scenarios) {
                String node = "sc" + (++k);
                mm.append("  route -->|\"").append(esc(f.label(s))).append("\"| ").append(node).append("[\"").append(esc(f.label(s) + " handling"))
                        .append("\"]\n");
                mm.append("  ").append(node).append(" --> build\n");
            }
            mm.append("  build[\"Build the result record\"]\n");
            prev = "build";
            steps.add("**Handle it.** The handler for that kind of work applies its rules and calculations and produces one result record "
                    + "(details per kind of work in [F03](F03_Business_Scenarios_And_Rules.md)).");
        }
        for (Entity file : f.files) {
            String node = "write" + (++n);
            mm.append("  ").append(prev).append(" --> ").append(node).append("[\"Write ").append(esc(fileTitle(c, f, file.id().value()))).append(" (")
                    .append(esc(c.attr(file, "fieldCount"))).append(" fields per line)\"]\n");
            steps.add("**Write the output.** One line per record is written to the output file with " + c.attr(file, "fieldCount")
                    + " fields: " + c.fields().stream().filter(x -> file.id().value().equals(c.attr(x, "file")))
                    .map(x -> f.h.words(x.name())).collect(Collectors.joining(", ")) + " (positions in [F04](F04_Data_Dictionary.md)).");
            prev = node;
        }
        for (Entity u : f.updates) {
            String node = "save" + (++n);
            mm.append("  ").append(prev).append(" --> ").append(node).append("[\"").append(esc(cut(updateText(u, f), 110))).append("\"]\n");
            steps.add("**Save the result.** " + updateText(u, f) + ".");
            prev = node;
        }
        mm.append("  ").append(prev).append(" --> done([\"Finish\"])\n");
        sb.append(Md.h(2, "The flow"));
        sb.append(Md.block("mermaid", mm.toString()));
        sb.append("_The diagram shows the possible flow; the order of the technical calls is in [03](03_Execution_Flow.md)._\n\n");
        sb.append(Md.h(2, "Step by step"));
        for (int i = 0; i < steps.size(); i++) {
            sb.append(i + 1).append(". ").append(steps.get(i)).append('\n');
        }
        sb.append('\n');
        sb.append(Md.h(2, "What can differ between kinds of work"));
        List<List<String>> diff = new ArrayList<>();
        for (Entity fld : c.fields()) {
            if ("true".equals(c.attr(fld, "derivationDiffersByScenario"))) {
                diff.add(List.of(f.h.words(fld.name()), "Differs by kind of work: see [F04](F04_Data_Dictionary.md)"));
            }
        }
        sb.append(Md.table(List.of("Output field", "Note"), diff));
        return sb.toString();
    }

    private static List<String> readTablesOf(DocContext c, Entity s, Facts f) {
        Matcher m = Pattern.compile("(?i)\\bFROM\\s+(\\w+)").matcher(c.attr(s, "text") == null ? "" : c.attr(s, "text"));
        List<String> out = new ArrayList<>();
        while (m.find()) {
            out.add(f.h.words(m.group(1)));
        }
        return out.isEmpty() ? List.of("the database") : out;
    }

    private static String esc(String s) {
        return s == null ? "" : s.replace("\"", "#quot;").replace("<", "#lt;").replace(">", "#gt;").replace("\n", " ").replace("|", "#124;");
    }

    private static String cut(String s, int max) {
        return s.length() <= max ? s : s.substring(0, max - 1) + "…";
    }

    // ================================================================ F03 scenarios and rules

    static String scenarios(DocContext c) {
        Facts f = new Facts(c);
        StringBuilder sb = new StringBuilder(header("F03 Business scenarios and rules",
                "For each kind of work: when it applies, what it decides, what it calculates and what it produces."));
        if (f.scenarios.isEmpty()) {
            sb.append("_No scenario (kind of work) was discovered. The decisions of every method that branches are listed in "
                    + "[14](14_Decision_Paths.md); the plain-language version of the rules follows._\n\n");
        }
        for (Entity s : f.scenarios) {
            sb.append(Md.h(2, f.label(s) + " — " + f.h.words(s.name())));
            sb.append(Md.bullet("Applies when", f.h.condition(c.attr(s, "trigger"))));
            sb.append(Md.bullet("Described in the code as", commentOf(c, c.attr(s, "handlerClass"))));
            sb.append(Md.bullet("Data used", c.attr(s, "columnsRead") == null ? null : Arrays.stream(c.attr(s, "columnsRead").split(", "))
                    .map(col -> columnWords(col, f)).collect(Collectors.joining(", "))));
            sb.append(Md.bullet("Output fields filled", c.attr(s, "outputFields") == null ? null : Arrays.stream(c.attr(s, "outputFields").split(", "))
                    .map(x -> f.h.words(x)).collect(Collectors.joining(", "))));
            sb.append(Md.bullet("Confidence", confidence(c.attr(s, "status"))));
            sb.append('\n');
            List<Entity> methods = c.index.in(s.id(), RelationType.PART_OF_SCENARIO).stream().map(r -> r.from())
                    .filter(id -> id.type() == EntityType.METHOD).map(c.index::entity).sorted(Comparator.comparing(Entity::name)).toList();
            boolean any = false;
            for (Entity m : methods) {
                if (f.isFormatting(m.id().value())) {
                    continue;
                }
                any |= methodSection(c, f, sb, m, 3);
            }
            Set<String> ruleIds = ruleIdsOf(c, s, methods);
            sb.append(calculations(c, f, ruleIds));
            if (!any && ruleIds.isEmpty()) {
                sb.append("_This kind of work has no decision or calculation of its own._\n\n");
            }
        }
        // methods with decisions that are not part of a scenario
        Set<String> inScenario = new HashSet<>();
        f.scenarios.forEach(s -> c.index.in(s.id(), RelationType.PART_OF_SCENARIO).forEach(r -> inScenario.add(r.from().value())));
        List<Entity> others = c.of(EntityType.METHOD).stream()
                .filter(m -> !inScenario.contains(m.id().value()) && !f.isFormatting(m.id().value()) && !"true".equals(c.attr(m, "external"))
                        && !pathsOf(c, m).isEmpty()).sorted(Comparator.comparing(Entity::name)).toList();
        if (!others.isEmpty()) {
            sb.append(Md.h(2, "Other decisions in the application"));
            sb.append("_Decisions in code that is not part of one kind of work (shared helpers, the job itself)._\n\n");
            for (Entity m : others) {
                methodSection(c, f, sb, m, 3);
            }
        }
        return sb.toString();
    }

    /** The code comment on an entity (a class, method or field id), or null. */
    static String commentOf(DocContext c, String entityId) {
        if (entityId == null) {
            return null;
        }
        return c.model.entity(new EntityId(entityId)).map(e -> c.attr(e, "doc")).filter(d -> !d.isBlank()).orElse(null);
    }

    /** Pre-filled for the business to confirm: what the author wrote next to the code, marked as such. */
    static String definitionFromComment(DocContext c, String entityId) {
        String doc = commentOf(c, entityId);
        return doc == null ? "—" : "(from a code comment, confirm) " + doc;
    }

    private static String confidence(String status) {
        return switch (status == null ? "" : status) {
            case "VERIFIED" -> "High: every step from the data to the result was traced in the code";
            case "PARTIAL" -> "Medium: at least one step passes through something the analysis could only approximate; see F06";
            default -> "Low: some values could not be traced; see F06";
        };
    }

    private static String columnWords(String col, Facts f) {
        int dot = col.indexOf('.');
        return dot < 0 ? f.h.words(col) : f.h.column(col.substring(0, dot), col.substring(dot + 1));
    }

    private static Set<String> ruleIdsOf(DocContext c, Entity scenario, List<Entity> methods) {
        Set<String> ids = new TreeSet<>();
        String attr = c.attr(scenario, "rules");
        if (attr != null) {
            ids.addAll(Arrays.asList(attr.split(", ")));
        }
        return ids;
    }

    /** Paths of a method (not of its lambdas), by unit, in order. */
    private static List<Entity> pathsOf(DocContext c, Entity method) {
        return c.of(EntityType.PATH).stream().filter(p -> method.id().value().equals(c.attr(p, "method")) && c.attr(p, "unit") == null)
                .sorted(Comparator.comparingInt(p -> Integer.parseInt(c.attr(p, "number")))).toList();
    }

    private static boolean methodSection(DocContext c, Facts f, StringBuilder sb, Entity method, int level) {
        List<Entity> paths = pathsOf(c, method);
        if (paths.isEmpty()) {
            return false;
        }
        sb.append(Md.h(level, "Decisions in " + f.h.words(c.method(method.id().value()).replace('.', ' ').replace("constructor", "creation"))));
        String comment = commentOf(c, method.id().value());
        if (comment != null) {
            sb.append("_Code comment: ").append(comment).append("_\n\n");
        }
        sb.append("_Possible ways this step can go (").append(paths.size()).append("). Each row is one way; technical detail in [14](14_Decision_Paths.md)._\n\n");
        List<List<String>> rows = new ArrayList<>();
        int n = 0;
        for (Entity p : paths) {
            n++;
            rows.add(List.of(String.valueOf(n), whenText(c, f, p), thenText(c, f, p), resultText(c, f, p)));
        }
        sb.append(Md.table(List.of("#", "When", "Then", "Result"), rows));
        if (paths.size() >= 2 && paths.size() <= DIAGRAM_PATH_LIMIT) {
            sb.append(Md.block("mermaid", decisionDiagram(c, f, paths)));
        }
        return true;
    }

    private static List<String> atoms(DocContext c, Entity path) {
        String a = c.attr(path, "atoms");
        return a == null || a.isEmpty() ? List.of() : Arrays.asList(a.split(" ;; "));
    }

    private static String whenText(DocContext c, Facts f, Entity p) {
        List<String> atoms = atoms(c, p);
        return atoms.isEmpty() ? "always" : atoms.stream().map(f.h::condition).collect(Collectors.joining(" and "));
    }

    private static String thenText(DocContext c, Facts f, Entity p) {
        String list = c.attr(p, "thenList");
        if (list == null || list.isEmpty()) {
            return "no other change";
        }
        return Arrays.stream(list.split(" ;; ")).map(f.h::effect).collect(Collectors.joining("; "));
    }

    private static String resultText(DocContext c, Facts f, Entity p) {
        String exit = c.attr(p, "exit");
        String value = c.attr(p, "value");
        return switch (exit == null ? "" : exit) {
            case "RETURN" -> value == null ? "finishes" : "returns " + f.h.value(value);
            case "THROW" -> "stops with an error" + (value == null ? "" : ": " + f.h.value(value));
            case "BREAK", "CONTINUE" -> "moves on";
            default -> "continues";
        };
    }

    /** The paths as a decision tree: each edge is a condition, each leaf what happens. */
    private static String decisionDiagram(DocContext c, Facts f, List<Entity> paths) {
        StringBuilder mm = new StringBuilder("flowchart TD\n  n0([\"Start\"])\n");
        Map<String, String> nodeOf = new LinkedHashMap<>();
        nodeOf.put("", "n0");
        int[] counter = {0};
        Set<String> edges = new LinkedHashSet<>();
        for (Entity p : paths) {
            String prefix = "";
            String parent = "n0";
            for (String atom : atoms(c, p)) {
                String key = prefix + "\u0001" + atom;
                String node = nodeOf.get(key);
                if (node == null) {
                    node = "n" + (++counter[0]);
                    nodeOf.put(key, node);
                    edges.add("  " + parent + " -->|\"" + esc(cut(f.h.condition(atom), 80)) + "\"| " + node + "{\"next check\"}");
                }
                prefix = key;
                parent = node;
            }
            String leaf = "n" + (++counter[0]);
            String then = thenText(c, f, p);
            String text = cut((then.equals("no other change") ? "" : then + " — ") + resultText(c, f, p), 140);
            edges.add("  " + parent + " --> " + leaf + "[\"" + esc(text) + "\"]");
        }
        edges.forEach(e -> mm.append(e).append('\n'));
        return mm.toString();
    }

    /** Calculations of the scenario: computation rules and the effects that give a value, with the conditions they sit under. */
    private static String calculations(DocContext c, Facts f, Set<String> ruleIds) {
        List<List<String>> rows = new ArrayList<>();
        for (String id : ruleIds) {
            Optional<Entity> rule = c.model.entity(new EntityId(id));
            if (rule.isEmpty() || f.isFormatting(c.attr(rule.get(), "method"))) {
                continue;
            }
            Entity r = rule.get();
            String effects = c.attr(r, "effects") == null ? Md.NONE : Arrays.stream(c.attr(r, "effects").split(" ; ")).map(f.h::effect).collect(Collectors.joining("; "));
            rows.add(List.of(c.ruleLabel(id), c.attr(r, "conditions") == null ? "always" : f.h.condition(c.attr(r, "conditions")), effects));
        }
        if (rows.isEmpty()) {
            return "";
        }
        return Md.h(3, "Rules and calculations") + Md.table(List.of("Rule", "When", "What it does"), rows);
    }

    // ================================================================ F07 field reference

    static String fieldReference(DocContext c) {
        Facts f = new Facts(c);
        List<Entity> fields = c.fields();
        Map<String, List<LineageCards.Card>> cards = fieldCards(c, f);
        return FieldReference.build(c, f.h, header("F07 Field reference",
                "One section per output field, with the path from the field back to its table columns, the path from each column down to the fields it feeds, "
                        + "and what changes a field's value (zone, transaction type, codes)."),
                fields, cards, x -> fileTitle(c, f, c.attr(x, "file")));
    }

    private static Map<String, List<LineageCards.Card>> fieldCards(DocContext c, Facts f) {
        Map<String, String> labels = new HashMap<>();
        f.scenarios.forEach(s -> labels.put(s.name(), f.label(s)));
        Set<String> prefixes = f.formattingPrefixes.stream().map(p -> p.startsWith("method:") ? p.substring(7) : p).collect(Collectors.toSet());
        Map<String, List<LineageCards.Card>> cards = new LinkedHashMap<>();
        for (Entity x : c.fields()) {
            cards.put(x.name(), LineageCards.build(c, x, prefixes, labels));
        }
        return cards;
    }

    private static String plain(String s) {
        return s.replace("**", "").replace("`", "");
    }

    /** One section per output field: everything the engine knows about how the value comes about, as citable facts for the AI to write an end-to-end explanation. */
    private static List<Narration.Section> fieldSections(DocContext c, Facts f) {
        List<Narration.Section> out = new ArrayList<>();
        Map<String, List<LineageCards.Card>> cards = fieldCards(c, f);
        for (Entity x : c.fields()) {
            String w = f.h.words(x.name());
            String id = "D:" + x.name();
            List<Narration.Fact> facts = new ArrayList<>();
            facts.add(fact(id + ":POS", "Output field " + w + " is written to " + fileTitle(c, f, c.attr(x, "file")) + " at characters " + c.attr(x, "start")
                    + " to " + c.attr(x, "end") + ", " + c.attr(x, "width") + " characters wide."));
            Map<String, Set<String>> varies = new LinkedHashMap<>();
            String type = null;
            for (LineageCards.Card card : cards.getOrDefault(x.name(), List.of())) {
                String k = id + ":" + card.scenario();
                for (LineageCards.Source s : card.sources()) {
                    facts.add(fact(k + ":SRC:" + s.key(), "For " + card.scenario() + ", the value comes from table " + s.table() + ", column " + s.column()
                            + (s.type() == null ? "" : " (data type " + s.type() + ")") + (s.query() == null ? "" : ". " + s.query())));
                    type = type == null ? s.type() : type;
                }
                int n = 0;
                for (LineageCards.Step st : card.steps()) {
                    String where = c.model.entity(new EntityId(st.id())).map(c::loc).orElse("");
                    facts.add(fact(k + ":STEP" + (++n), "For " + card.scenario() + ", calculation step " + n + ": " + st.name() + " is set to " + st.formula()
                            + (st.when().isEmpty() ? "" : " only when " + st.when()) + (where.isEmpty() ? "" : ". Evidence: " + where)));
                }
                if (!card.chosen().isEmpty()) {
                    facts.add(fact(k + ":CHOICE", "For " + card.scenario() + ", the value is chosen by a condition: " + String.join("; ", card.chosen()) + "."));
                }
                for (LineageCards.Source s : card.deciders()) {
                    facts.add(fact(k + ":DECIDER:" + s.key(), "For " + card.scenario() + ", the choice depends on table " + s.table() + ", column " + s.column() + "."));
                }
                for (String v : card.fixed()) {
                    facts.add(fact(k + ":FIXED:" + Math.abs(v.hashCode()), "For " + card.scenario() + ", the value is fixed: " + v + "."));
                }
                for (String u : card.unknown()) {
                    facts.add(fact(k + ":UNKNOWN:" + Math.abs(u.hashCode()), "For " + card.scenario() + ", the source cannot be traced: " + u + "."));
                }
                card.varies().forEach((a, conds) -> varies.computeIfAbsent(a, q -> new LinkedHashSet<>()).addAll(conds));
            }
            varies.forEach((a, conds) -> facts.add(fact(id + ":VARIES:" + a, "The value changes with " + a + ": " + String.join("; ", conds) + ".")));
            FormatRecipe.Result fr = FormatRecipe.of(c, f.h, x, type);
            if (fr.resolved()) {
                int n = 0;
                for (String step : fr.steps()) {
                    facts.add(fact(id + ":FMT" + (++n), "Writing to the file, step " + n + ": " + plain(step) + "."));
                }
                n = 0;
                for (String ex : fr.exampleFacts()) {
                    facts.add(fact(id + ":EX" + (++n), ex));
                }
                if (fr.widthCheck() != null) {
                    facts.add(fact(id + ":WIDTH", "Width check: " + plain(fr.widthCheck())));
                }
            }
            out.add(new Narration.Section("field-" + x.name(), "Field " + w + ": how its value is derived, from the table column to the file", facts));
        }
        return out;
    }

    // ================================================================ F04 data dictionary

    static String dataDictionary(DocContext c) {
        Facts f = new Facts(c);
        StringBuilder sb = new StringBuilder(header("F04 Data dictionary",
                "Every output field: where it sits in the file, where its value comes from (table and column), how it is calculated, and how it is formatted."));
        List<Entity> fields = c.fields();
        if (fields.isEmpty()) {
            return sb.append("_No fixed-width output field was found._\n").toString();
        }
        Map<String, String> labels = new HashMap<>();
        f.scenarios.forEach(s -> labels.put(s.name(), f.label(s)));
        Map<String, List<LineageCards.Card>> cards = new LinkedHashMap<>();
        for (Entity x : fields) {
            cards.put(x.name(), LineageCards.build(c, x, f.formattingPrefixes.stream().map(p -> p.startsWith("method:") ? p.substring(7) : p).collect(Collectors.toSet()), labels));
        }
        sb.append(Md.h(2, "Where every value comes from"));
        sb.append("_One row per field and kind of work. The cards below show the calculation step by step._\n\n");
        List<List<String>> summary = new ArrayList<>();
        for (Entity x : fields) {
            for (LineageCards.Card card : cards.get(x.name())) {
                List<String> where = new ArrayList<>();
                card.sources().forEach(s -> where.add(Md.code(s.key())));
                if (!card.chosen().isEmpty()) {
                    where.add("one of " + String.join(" / ", card.chosen().stream().map(v -> v.replaceAll(" when .*$", "")).toList()));
                }
                where.addAll(card.fixed().stream().map(v -> v.replaceAll(" when .*$", "")).toList());
                where.addAll(card.unknown());
                summary.add(List.of(f.h.words(x.name()), card.scenario(), String.join(", ", where), card.how(), String.valueOf(c.attr(x, "traceStatus"))));
            }
        }
        sb.append(Md.table(List.of("Output field", "Kind of work", "Source (table.column or value)", "How", "Confidence"), summary));
        for (Entity x : fields) {
            sb.append(Md.h(2, f.h.words(x.name())));
            sb.append(Md.bullet("Written to", fileTitle(c, f, c.attr(x, "file")) + ", characters " + c.attr(x, "start") + " to " + c.attr(x, "end")
                    + " (" + c.attr(x, "width") + " wide)"));
            String layout = LineageCards.layout(c, x);
            sb.append(Md.bullet("Layout", layout != null ? layout : "width " + c.attr(x, "width") + "; alignment and padding are not stated by the analysis"));
            sb.append(Md.bullet("Technical name", Md.code(x.name())));
            sb.append(Md.bullet("Confidence", confidence(c.attr(x, "traceStatus"))));
            if (c.answers.containsKey("source." + x.name())) {
                sb.append(Md.bullet("Business answer (provided)", c.answers.get("source." + x.name())));
            }
            sb.append('\n');
            for (LineageCards.Card card : cards.get(x.name())) {
                sb.append(LineageCards.render(card, f.h));
            }
        }
        return sb.toString();
    }

    /** The output file in words: "the manifest file" for {@code ManifestWriter.write}; the code name stays in the technical documents. */
    static String fileTitle(DocContext c, Facts f, String fileId) {
        if (fileId == null) {
            return Md.NONE;
        }
        String name = c.nameOf(fileId);
        int dot = name.indexOf('.');
        String type = dot < 0 ? name : name.substring(0, dot);
        String words = f.h.words(type).replaceAll("\\s*(writer|generator|exporter)$", "").trim();
        return "the " + (words.isEmpty() ? "output" : words) + " file";
    }

    /** Where the value starts: a column it depends on, a fixed value, a run-time input, or something that could not be traced. */
    private static String sourceBase(DocContext c, Facts f, Entity t) {
        String kind = c.attr(t, "terminalKind");
        String terminal = c.attr(t, "terminal");
        String id = c.attr(t, "terminalId");
        return switch (kind == null ? "" : kind) {
            case "column" -> "Depends on " + columnWords(id == null ? terminal : id.substring(id.indexOf(':') + 1), f)
                    + " (column " + Md.code(id == null ? terminal : id.substring(id.indexOf(':') + 1)) + ")";
            case "constant" -> "Fixed value: " + f.h.value(terminal);
            case "runtime input", "entry input" -> "Supplied when the job runs: " + f.h.value(terminal) + " — **confirm with the business**";
            case "external call" -> "Comes from outside the analysed code: " + f.h.value(terminal) + " — **confirm with the business**";
            case "field initialiser" -> "Starts with the value of " + f.h.value(terminal);
            default -> "Could not be traced: " + (terminal == null ? Md.NONE : terminal) + " — **confirm with the business**";
        };
    }

    /** What the business rules on the way do to the value, each with the condition it applies under. */
    private static List<String> ruleLines(DocContext c, Facts f, Entity t) {
        List<String> out = new ArrayList<>();
        String rules = c.attr(t, "rules");
        if (rules == null) {
            return out;
        }
        List<Entity> usable = new ArrayList<>();
        for (String ruleId : new TreeSet<>(Arrays.asList(rules.split(", ")))) {
            Optional<Entity> r = c.model.entity(new EntityId(ruleId));
            if (r.isPresent() && !f.isFormatting(c.attr(r.get(), "method"))) {
                usable.add(r.get());
            }
        }
        for (Entity r : usable) {
            String cond = c.attr(r, "conditions");
            String effects = c.attr(r, "effects") == null ? "" : Arrays.stream(c.attr(r, "effects").split(" ; ")).map(f.h::effect)
                    .collect(Collectors.joining("; "));
            out.add((cond == null ? "always" : "when " + f.h.condition(cond)) + ": " + effects);
        }
        return out;
    }

    // ================================================================ F05 glossary

    static String glossary(DocContext c) {
        Facts f = new Facts(c);
        StringBuilder sb = new StringBuilder(header("F05 Glossary", "The terms used in the code, spelled out. Meanings are for the business to confirm."));
        sb.append("> Terms are spelled out from names in the code. **A spelled-out name is not a definition.** Add the business meaning to "
                + "`glossary.properties` next to these documents (`name = business term`) and regenerate with the `docs` command; the "
                + "term will then be used everywhere.\n\n");
        sb.append(Md.h(2, "Kinds of work (status values)"));
        List<List<String>> sc = new ArrayList<>();
        for (Entity s : f.scenarios) {
            sc.add(List.of(f.label(s), f.h.words(s.name()), "Selected when " + f.h.condition(c.attr(s, "trigger")), definitionFromComment(c, c.attr(s, "handlerClass"))));
        }
        sb.append(Md.table(List.of("Value", "Handled by", "Meaning in the code", "Business definition (to confirm)"), sc));

        sb.append(Md.h(2, "Data fields (database columns)"));
        Map<String, TreeSet<String>> readBy = new TreeMap<>();
        for (Entity s : f.scenarios) {
            if (c.attr(s, "columnsRead") != null) {
                for (String col : c.attr(s, "columnsRead").split(", ")) {
                    readBy.computeIfAbsent(col, k -> new TreeSet<>()).add(f.label(s));
                }
            }
        }
        List<List<String>> cols = new ArrayList<>();
        for (Entity col : c.of(EntityType.COLUMN).stream().sorted(Comparator.comparing(e -> e.id().value())).toList()) {
            String key = ModelIndex.key(col.id());
            int dot = key.indexOf('.');
            if (dot < 0) {
                continue;
            }
            cols.add(List.of(Md.code(key), columnWords(key, f), String.valueOf(c.attr(col, "type") == null ? Md.NONE : c.attr(col, "type")),
                    readBy.containsKey(key) ? String.join(", ", readBy.get(key)) : "not used by a traced kind of work", "—"));
        }
        sb.append(Md.table(List.of("Column", "Spelled out", "Data type", "Used by", "Business definition (to confirm)"), cols));

        sb.append(Md.h(2, "Fixed values (constants)"));
        List<List<String>> consts = new ArrayList<>();
        for (Entity fld : c.of(EntityType.FIELD)) {
            String mods = Optional.ofNullable(c.attr(fld, "modifiers")).orElse("");
            if (mods.contains("static") && mods.contains("final") && c.attr(fld, "initializer") != null && !"true".equals(c.attr(fld, "external"))) {
                consts.add(List.of(Md.code(fld.name()), f.h.words(fld.name()), f.h.value(c.attr(fld, "initializer")), c.loc(fld), definitionFromComment(c, fld.id().value())));
            }
        }
        sb.append(Md.table(List.of("Name", "Spelled out", "Value", "Where defined", "Business definition (to confirm)"), consts));

        sb.append(Md.h(2, "Output fields"));
        List<List<String>> out = new ArrayList<>();
        for (Entity x : c.fields()) {
            out.add(List.of(Md.code(x.name()), f.h.words(x.name()), "—"));
        }
        sb.append(Md.table(List.of("Name", "Spelled out", "Business definition (to confirm)"), out));

        sb.append(Md.h(2, "How names are spelled out"));
        sb.append("- Words are split at capital letters and underscores (`newTotal` reads \"new total\", `rate_pct` reads \"rate percent\").\n");
        sb.append("- These abbreviations are written in full: pct (percent), amt (amount), qty (quantity), num (number), dt (date), cd (code), "
                + "desc (description), addr (address), txn (transaction), cnt (count), "
                + "flg (flag), max (maximum), min (minimum), ts (timestamp), ref (reference), seq (sequence).\n");
        sb.append("- `glossary.properties` entries win over all of this: `ratePct = discount rate`, `item.rate_pct = discount rate`.\n");
        return sb.toString();
    }

    // ================================================================ F06 questions

    /** Something only a person can say. {@code key} is what the business writes in {@code answers.properties} (or {@code glossary.properties} for constants). */
    record Open(String key, String about, String question, String type, boolean blocking) {}

    /** Everything the analysis could not establish, with a stable key for each. */
    static List<Open> openItems(DocContext c) {
        Facts f = new Facts(c);
        Map<String, Open> items = new LinkedHashMap<>();
        for (Entity x : c.fields()) {
            Set<String> scenarios = new LinkedHashSet<>();
            String terminal = null;
            for (Map.Entry<Entity, TraceStatus> e : c.traces(x)) {
                String kind = c.attr(e.getKey(), "terminalKind");
                if ("runtime input".equals(kind) || "external call".equals(kind) || "untraced".equals(kind)) {
                    scenarios.add(Optional.ofNullable(c.attr(e.getKey(), "scenario")).orElse("(all)"));
                    terminal = c.attr(e.getKey(), "terminal");
                }
            }
            if (terminal != null) {
                items.put("source." + x.name(), new Open("source." + x.name(), f.h.words(x.name()) + " (" + String.join(", ", scenarios) + ")",
                        "The value comes from " + f.h.value(terminal) + ", which the code analysis cannot follow. Where does it really come from, who maintains it and what values are valid?",
                        "Data source", true));
            }
        }
        Set<String> tracedRules = new HashSet<>();
        for (Entity t : c.of(EntityType.TRANSFORMATION)) {
            if (c.attr(t, "rules") != null) {
                tracedRules.addAll(Arrays.asList(c.attr(t, "rules").split(", ")));
            }
        }
        for (Entity r : c.of(EntityType.BUSINESS_RULE).stream().sorted(Comparator.comparing(e -> c.ruleLabel(e.id().value()))).toList()) {
            if ("PARTIAL".equals(c.attr(r, "traceStatus")) && !f.isFormatting(c.attr(r, "method")) && tracedRules.contains(r.id().value())) {
                String cond = c.attr(r, "conditions") == null ? "" : " when " + f.h.condition(c.attr(r, "conditions"));
                String key = "rule." + c.ruleLabel(r.id().value());
                items.put(key, new Open(key, c.ruleLabel(r.id().value()) + " in " + c.method(c.attr(r, "method")),
                        "This rule" + cond + " " + Arrays.stream(String.valueOf(c.attr(r, "effects")).split(" ; ")).map(f.h::effect).collect(Collectors.joining("; "))
                                + ", but part of it depends on something outside the analysed code. Is the result correct and complete?", "Rule", true));
            }
        }
        Set<String> seen = new TreeSet<>();
        for (Entity r : c.of(EntityType.BUSINESS_RULE).stream().sorted(Comparator.comparing(e -> c.ruleLabel(e.id().value()))).toList()) {
            String literals = c.attr(r, "literals");
            String numbers = literals == null ? "" : Arrays.stream(literals.split(", ")).filter(x -> x.matches("\\d+(\\.\\d+)?") && !Set.of("0", "1", "2").contains(x)).collect(Collectors.joining(", "));
            if (!numbers.isEmpty() && !f.isFormatting(c.attr(r, "method")) && tracedRules.contains(r.id().value()) && seen.add(numbers)) {
                String key = "number." + c.ruleLabel(r.id().value());
                items.put(key, new Open(key, c.ruleLabel(r.id().value()) + " in " + c.method(c.attr(r, "method")),
                        "The calculation uses the fixed number(s) " + numbers + ". What do they mean and are they still current?", "Fixed value", true));
            }
        }
        for (Entity fld : c.of(EntityType.FIELD)) {
            String mods = Optional.ofNullable(c.attr(fld, "modifiers")).orElse("");
            if (mods.contains("static") && mods.contains("final") && c.attr(fld, "initializer") != null && !"true".equals(c.attr(fld, "external"))
                    && c.attr(fld, "initializer").matches(".*\\d.*") && seen.add(fld.name())) {
                items.put(fld.name(), new Open(fld.name(), f.h.words(fld.name()) + " = " + f.h.value(c.attr(fld, "initializer")),
                        "What does this fixed value represent, who sets it and how often does it change? (answer in glossary.properties under " + fld.name() + ")", "Fixed value", true));
            }
        }
        for (Entity d : c.of(EntityType.PATH_DECISION)) {
            if ("false".equals(c.attr(d, "reachable"))) {
                String key = "logic." + c.method(c.attr(d, "method")) + "@" + c.attr(d, "line");
                items.put(key, new Open(key, c.method(c.attr(d, "method")) + " line " + c.attr(d, "line"),
                        "The code has a decision (" + f.h.condition(c.attr(d, "condition")) + ") where one outcome can never happen. Is this old or unfinished logic?", "Unreachable logic", true));
            }
        }
        if (c.glossarySize() == 0) {
            items.put("glossary", new Open("glossary", "Glossary", "No business names were supplied. Review F05 and add the business term for each name.", "Naming", false));
        }
        if (!c.answers.containsKey("system.purpose")) {
            items.put("system.purpose", new Open("system.purpose", "The application", "What is this application for, in one or two sentences, and who uses its output?", "Context", true));
        }
        return new ArrayList<>(items.values());
    }

    static boolean answered(DocContext c, Open o) {
        return c.answers.containsKey(o.key()) || c.humanizer.hasTerm(o.key());
    }

    static String questions(DocContext c) {
        StringBuilder sb = new StringBuilder(header("F06 Questions for business experts",
                "What the code cannot say by itself. Each item needs a person who knows the business."));
        List<Open> all = openItems(c);
        List<List<String>> open = new ArrayList<>();
        List<List<String>> done = new ArrayList<>();
        int n = 0;
        for (Open o : all) {
            if (answered(c, o)) {
                done.add(List.of(Md.code(o.key()), o.about(), c.answers.getOrDefault(o.key(), "see glossary")));
            } else {
                open.add(List.of("Q" + (++n), Md.code(o.key()), o.about(), o.question(), o.type()));
            }
        }
        if (c.humanizer.unparsed() > 0) {
            open.add(List.of("Q" + (++n), Md.NONE, "Wording", c.humanizer.unparsed() + " condition(s) or calculation(s) in these documents are shown as code because they are too complex to rewrite safely; a developer should explain them.", "Wording"));
        }
        sb.append("> Answer in `answers.properties` (in the `context` folder next to the documents): one line per key, `key = your answer`. "
                + "For fixed values and names use `glossary.properties`. Then run the pipeline again: the answers appear in the documents.\n\n");
        sb.append(Md.h(2, "Open"));
        sb.append(open.isEmpty() ? "_Nothing is open. Review F03 and F04 against the business rules you know._\n\n"
                : Md.table(List.of("#", "Key", "About", "Question", "Type"), open));
        if (!done.isEmpty()) {
            sb.append(Md.h(2, "Answered"));
            sb.append(Md.table(List.of("Key", "About", "Answer"), done));
        }
        return sb.toString();
    }

    // ================================================================ facts for AI narration

    private static final int FACT_LIMIT = 600;

    private static Narration.Fact fact(String id, String text) {
        String flat = text.replace("`", "").replaceAll("\\s+", " ").trim();
        return new Narration.Fact(id, flat.length() <= FACT_LIMIT ? flat : flat.substring(0, FACT_LIMIT - 1) + "…");
    }

    /**
     * The verified facts an AI may reword, in sections small enough to paste into a chat window. Every fact is a sentence this
     * engine already derived (the same ones as in F01 to F06) with an ID the AI must cite. Nothing is added here that the model does not hold.
     */
    static List<Narration.Section> narrationSections(DocContext c) {
        Facts f = new Facts(c);
        List<Narration.Section> out = new ArrayList<>();

        List<Narration.Fact> overview = new ArrayList<>();
        overview.add(fact("O:START", "The job is started by " + f.entryText() + "."));
        int n = 0;
        for (Entity s : f.selects) {
            overview.add(fact("O:READ" + (++n), "It reads " + String.join(", ", readTablesOf(c, s, f)) + " records where " + filterText(c.attr(s, "predicates"), f.h) + "."));
        }
        for (Entity s : f.scenarios) {
            String doc = commentOf(c, c.attr(s, "handlerClass"));
            overview.add(fact("O:KIND:" + f.label(s), "Kind of work " + f.label(s) + " applies when " + f.h.condition(c.attr(s, "trigger"))
                    + "." + (doc == null ? "" : " Code comment: " + doc)));
        }
        for (Entity file : f.files) {
            overview.add(fact("O:OUT:" + c.name(file.id()), "It writes " + fileTitle(c, f, file.id().value()) + " with " + c.attr(file, "fieldCount") + " fields per line: "
                    + c.fields().stream().filter(x -> file.id().value().equals(c.attr(x, "file"))).map(x -> f.h.words(x.name())).collect(Collectors.joining(", ")) + "."));
        }
        n = 0;
        for (Entity u : f.updates) {
            overview.add(fact("O:SAVE" + (++n), "It saves results back: " + updateText(u, f) + "."));
        }
        out.add(new Narration.Section("overview", "Business overview: what the application does from start to finish", overview));

        for (Entity s : f.scenarios) {
            String label = f.label(s);
            List<Narration.Fact> facts = new ArrayList<>();
            facts.add(fact("S:" + label + ":APPLIES", "Kind of work " + label + " applies when " + f.h.condition(c.attr(s, "trigger")) + "."));
            String doc = commentOf(c, c.attr(s, "handlerClass"));
            if (doc != null) {
                facts.add(fact("S:" + label + ":COMMENT", "Code comment on the handler: " + doc));
            }
            List<Entity> methods = c.index.in(s.id(), RelationType.PART_OF_SCENARIO).stream().map(r -> r.from())
                    .filter(id -> id.type() == EntityType.METHOD).map(c.index::entity).sorted(Comparator.comparing(Entity::name)).toList();
            for (Entity m : methods) {
                if (f.isFormatting(m.id().value())) {
                    continue;
                }
                List<Entity> paths = pathsOf(c, m);
                int p = 0;
                for (Entity path : paths) {
                    p++;
                    facts.add(fact("S:" + label + ":" + m.name() + ":P" + p, "In " + f.h.words(m.name()) + ", way " + p + " of " + paths.size() + ": when "
                            + whenText(c, f, path) + ", " + thenText(c, f, path) + ", and it " + resultText(c, f, path) + "."));
                }
            }
            for (String ruleId : ruleIdsOf(c, s, methods)) {
                Optional<Entity> rule = c.model.entity(new EntityId(ruleId));
                if (rule.isPresent() && !f.isFormatting(c.attr(rule.get(), "method")) && c.attr(rule.get(), "effects") != null) {
                    facts.add(fact("R:" + c.ruleLabel(ruleId), (c.attr(rule.get(), "conditions") == null ? "Always" : "When " + f.h.condition(c.attr(rule.get(), "conditions")))
                            + ": " + Arrays.stream(c.attr(rule.get(), "effects").split(" ; ")).map(f.h::effect).collect(Collectors.joining("; ")) + "."));
                }
            }
            for (Entity fld : c.fields()) {
                for (Map.Entry<Entity, TraceStatus> e : c.traces(fld)) {
                    if (s.name().equals(c.attr(e.getKey(), "scenario"))) {
                        String lines = String.join("; ", ruleLines(c, f, e.getKey()));
                        facts.add(fact("F:" + fld.name() + ":" + label, "Output field " + f.h.words(fld.name()) + " (" + label + "): " + sourceBase(c, f, e.getKey())
                                + (lines.isEmpty() ? "" : ". " + lines)));
                        break;
                    }
                }
            }
            out.add(new Narration.Section("scenario-" + label, "Kind of work " + label + ": what it decides, calculates and produces", facts));
        }

        List<Narration.Fact> questions = new ArrayList<>();
        n = 0;
        for (Entity x : c.fields()) {
            for (Map.Entry<Entity, TraceStatus> e : c.traces(x)) {
                String kind = c.attr(e.getKey(), "terminalKind");
                if ("runtime input".equals(kind) || "external call".equals(kind) || "untraced".equals(kind)) {
                    questions.add(fact("Q:" + (++n), "Output field " + f.h.words(x.name()) + " gets its value from " + f.h.value(c.attr(e.getKey(), "terminal"))
                            + ", which the code analysis cannot follow."));
                }
            }
        }
        if (!questions.isEmpty()) {
            out.add(new Narration.Section("open-questions", "Open questions: what needs a business expert to confirm", questions));
        }

        List<Narration.Fact> terms = new ArrayList<>();
        for (Entity fld : c.of(EntityType.FIELD)) {
            String mods = Optional.ofNullable(c.attr(fld, "modifiers")).orElse("");
            if (mods.contains("static") && mods.contains("final") && c.attr(fld, "initializer") != null && !"true".equals(c.attr(fld, "external"))) {
                String doc = commentOf(c, fld.id().value());
                terms.add(fact("T:" + fld.name(), "Constant " + fld.name() + " (spelled out: " + f.h.words(fld.name()) + ") has the fixed value "
                        + f.h.value(c.attr(fld, "initializer")) + "." + (doc == null ? "" : " Code comment: " + doc)));
            }
        }
        for (Entity col : c.of(EntityType.COLUMN).stream().sorted(Comparator.comparing(e -> e.id().value())).toList()) {
            String key = ModelIndex.key(col.id());
            if (key.contains(".")) {
                terms.add(fact("T:" + key, "Column " + key + " (spelled out: " + columnWords(key, f) + ")."));
            }
        }
        for (Entity x : c.fields()) {
            terms.add(fact("T:" + x.name(), "Output field " + x.name() + " (spelled out: " + f.h.words(x.name()) + ") sits at positions "
                    + c.attr(x, "start") + " to " + c.attr(x, "end") + "."));
        }
        out.add(new Narration.Section("terms", "Terms: propose business meanings for names (only when the facts or comments support one)", terms));
        out.addAll(fieldSections(c, f));
        return out;
    }

    /** Every glossary term with the evidence the code holds for it, as a worksheet the business fills in. Existing entries are left out. */
    static String glossaryWorksheet(DocContext c, Map<String, String> confirmed, Map<String, String> aiProposed) {
        Facts f = new Facts(c);
        StringBuilder sb = new StringBuilder("# Glossary worksheet (generated). Copy the lines you want into glossary.properties and fill in the business term.\n"
                + "# Lines starting with '#' are ignored. Entries already in glossary.properties are not listed again.\n"
                + "# 'AI-proposed' lines come from an AI reply that passed verification; they are suggestions, not confirmed meanings.\n\n");
        for (Narration.Fact t : narrationSections(c).stream().filter(s -> s.id().equals("terms")).flatMap(s -> s.facts().stream()).toList()) {
            String key = t.id().substring(2);
            if (confirmed.containsKey(key)) {
                continue;
            }
            sb.append("# ").append(t.text()).append('\n');
            if (aiProposed.containsKey(key)) {
                sb.append("# AI-proposed (unconfirmed): ").append(aiProposed.get(key)).append('\n');
            }
            sb.append('#').append(key).append(" = \n\n");
        }
        return sb.toString();
    }
}
